#!/bin/bash
# Живая функциональная проверка ADR-021 фаза 2a (audio.py -> parsers.py)
# после выката 31.08.2026: полный конвейер ffmpeg -> Silero VAD -> GigaAM
# на тестовом .ogg (синтетическая речь espeak-ng, тот же файл, что и
# gigaam-benchmark — качество распознавания на нём уже задокументировано
# как непроверяемое этим инструментарием, см. ADR-021). Здесь проверяется
# ДРУГОЕ: сам конвейер не падает технически, parse_file() роутит .ogg
# верно, веса не скачиваются заново (запечены на сборке). Ничего не
# оставляет на сервере кроме временного файла, который сам же удаляет.
set -euo pipefail
trap 'rm -f /tmp/gigaam-verify.ogg' EXIT
echo "" | base64 -d > /tmp/gigaam-verify.ogg
cd /opt/helm/compose
sudo docker compose run --rm -v /tmp/gigaam-verify.ogg:/tmp/test.ogg:ro   --entrypoint python3 helm-knowledge-worker -c "
import time
from pathlib import Path
from helm_core.knowledge.parsers import parse_file

t0 = time.monotonic()
result = parse_file(Path('/tmp/test.ogg'))
elapsed = time.monotonic() - t0

print('parser:', result.parser)
print('quality_ok:', result.quality_ok)
print('elapsed_seconds:', round(elapsed, 2))
print('text:', repr(result.text))
"
